import { render } from '@solidjs/web';
import { createCart } from './cart';

function Header(props) {
  return <h1>Shop · {props.cart.count()} in cart</h1>;
}

function Product(props) {
  return (
    <p>
      {props.name} <button onClick={props.cart.add}>Add to cart</button>
    </p>
  );
}

function Shop(props) {
  return (
    <>
      <Product name="Mug" cart={props.cart} />
      <Product name="Notebook" cart={props.cart} />
    </>
  );
}

function App() {
  const cart = createCart();
  return (
    <>
      <Header cart={cart} />
      <Shop cart={cart} />
    </>
  );
}

render(() => <App />, document.getElementById('app'));

import { createContext, createSignal, useContext } from 'solid-js';

export function createCart() {
  const [count, setCount] = createSignal(0);
  return { count, add: () => setCount((n) => n + 1) };
}

import { render } from '@solidjs/web';
import { CartProvider, useCart } from './cart';

function Header() {
  const cart = useCart();
  return <h1>Shop · {cart.count()} in cart</h1>;
}

function Product(props) {
  const cart = useCart();
  return (
    <p>
      {props.name} <button onClick={cart.add}>Add to cart</button>
    </p>
  );
}

function Shop() {
  return (
    <>
      <Product name="Mug" />
      <Product name="Notebook" />
    </>
  );
}

function App() {
  return (
    <CartProvider>
      <Header />
      <Shop />
    </CartProvider>
  );
}

render(() => <App />, document.getElementById('app'));

import { createContext, createSignal, useContext } from 'solid-js';

export function createCart() {
  const [count, setCount] = createSignal(0);
  return { count, add: () => setCount((n) => n + 1) };
}

const CartContext = createContext();

export function CartProvider(props) {
  return <CartContext value={createCart()}>{props.children}</CartContext>;
}

export function useCart() {
  return useContext(CartContext);
}
